{
  "id": 4,
  "knowledge": "Mesh Complexity Ratio (MCR)",
  "description": "Measures the topological complexity of a mesh relative to its resolution, helping identify overly complex or simplified archaeological models.",
  "definition": "MCR = \\frac{FacetFaces}{FacetVerts \\times FacetResMm^2} \\times 10^3, \\text{ where higher values indicate more complex meshes for a given resolution, capturing finer archaeological details.}"
}

{
  "id": 13,
  "knowledge": "High Fidelity Mesh",
  "description": "Defines criteria for high-fidelity 3D mesh models in archaeological documentation suitable for analytical studies.",
  "definition": "A mesh with MCR > 5.0, FacetResMm < 1.0, and GeomDeltaMm < 0.5, where MCR is the Mesh Complexity Ratio, capable of representing fine archaeological details and surface morphology."
}

{
  "id": 53,
  "knowledge": "Mesh Quality Classification",
  "description": "A standardized system for categorizing archaeological site documentation based on the presence and quality of 3D mesh models.",
  "definition": "A three-tier classification where 'Has High-Fidelity Meshes' indicates sites with at least one mesh meeting high-fidelity criteria, 'Standard Mesh Quality' indicates sites with meshes that don't meet high-fidelity standards, and 'No Mesh Data' indicates sites lacking 3D mesh documentation entirely. This classification helps prioritize additional documentation efforts and determines appropriate analytical approaches for different sites."
}

{
  "id": 20,
  "knowledge": "ScanResolMm (Scan Resolution)",
  "description": "Illustrates the significance of scan resolution measurements in archaeological scanning for feature detection.",
  "definition": "Measured in millimeters, representing the smallest feature that can be distinguished in the scan. Values like 0.5mm enable documentation of fine tool marks on artifacts, while 2.0mm might only capture general shape and macroscopic features."
}

{
  "id": 24,
  "knowledge": "GeomDeltaMm (Geometric Accuracy)",
  "description": "Illustrates the significance of geometric accuracy in 3D models for measurement reliability.",
  "definition": "Measured in millimeters, representing the average deviation between the scan data and final 3D model. Values below 0.1mm indicate museum-quality accuracy, while values around 1.0mm are suitable for general documentation but introduce uncertainty in fine feature analysis."
}

{
  "id": 6,
  "knowledge": "Model Fidelity Score (MFS)",
  "description": "Combines mesh complexity, texture quality, and geometric accuracy to assess overall 3D model fidelity for archaeological analysis.",
  "definition": "MFS = MCR \\times \\left(\\frac{TDI}{10}\\right) \\times \\left(1 + \\exp\\left(-GeomDeltaMm\\right)\\right), \\text{ where higher values indicate more accurate and detailed models with appropriate complexity.}"
}

{
  "id": 5,
  "knowledge": "Texture Density Index (TDI)",
  "description": "Evaluates the pixel density of textures relative to mesh resolution for assessing surface detail preservation.",
  "definition": "TDI = \\frac{TexPix}{\\sqrt{FacetFaces} \\times FacetResMm} \\times 10^{-2}, \\text{ where higher values indicate more detailed textures relative to geometric complexity.}"
}

args.sql:
SELECT facetfaces / (facetverts * POWER(facetresmm, 2)) * 1000 as mcr_power,
       facetfaces::numeric / (facetverts::numeric * facetresmm * facetresmm) * 1000 as mcr_direct
FROM scanmesh LIMIT 5;
